/* 학습 해설
 * IRQ 디버그 설정: 부팅 옵션과 런타임 매개변수의 적용 범위
 * 진단 기능을 끄거나 복구 탐색을 넓히는 설정은 실행 비용과 관찰 결과를 바꾸므로 이름만 외우지 말고 실제 setter의 범위를 알아야 합니다.
 * noirqdebug_setup은 입력 문자열을 해석하지 않고 noirqdebug=1로 만들고 메시지 후 1을 반환합니다. __setup이 noirqdebug 부팅 옵션에 연결하며 bool module_param은 권한 0644로 공개됩니다. irqfixup_setup은 PREEMPT_RT이면 경고 후 1을 반환하고 모드 값을 바꾸지 않으며 아니면 irqfixup=1입니다. irqpoll_setup도 RT에서는 바꾸지 않고 아니면 2입니다. 두 setup은 성능 영향을 알립니다. irqfixup은 별도로 int module_param이므로 부팅 setter 안의 RT 검사만으로 모든 런타임 쓰기까지 그 검사를 통과한다고 주장하면 안 됩니다.
 * 각 setup의 반환 1을 IRQ_HANDLED와 혼동하지 마세요. 여기서는 부팅 인자를 처리했다는 setup 계약입니다. __read_mostly는 배치 관련 표시이며 변수에 쓰기를 금지하는 const가 아닙니다. 학습 예제를 실제 시스템의 부팅 설정 변경과 구분하세요.
 */
int noirqdebug_setup(char *str)
{
	noirqdebug = 1;
	printk(KERN_INFO "IRQ lockup detection disabled\n");

	return 1;
}

__setup("noirqdebug", noirqdebug_setup);
module_param(noirqdebug, bool, 0644);
MODULE_PARM_DESC(noirqdebug, "Disable irq lockup detection when true");

static int __init irqfixup_setup(char *str)
{
	if (IS_ENABLED(CONFIG_PREEMPT_RT)) {
		pr_warn("irqfixup boot option not supported with PREEMPT_RT\n");
		return 1;
	}
	irqfixup = 1;
	printk(KERN_WARNING "Misrouted IRQ fixup support enabled.\n");
	printk(KERN_WARNING "This may impact system performance.\n");

	return 1;
}

__setup("irqfixup", irqfixup_setup);

/* 학습 해설
 * IRQ 디버그 비트 출력: 숫자 상태를 이름 표와 대조하기
 * 16진수 상태값만 보면 어떤 기능이 켜졌는지 읽기 어렵기 때문에 각 비트와 이름을 연결한 표로 사람이 읽을 수 있는 출력을 만듭니다.
 * irq_debug_show_bits는 size개 설명 항목을 순회하면서 state & sd->mask가 0이 아니면 sd->name을 출력합니다. 매 반복마다 i와 설명 포인터 sd를 함께 증가시킵니다. internals.h의 BIT_MASK_DESCR(m)은 .mask=m, .name=#m인 구조체 초기값을 만듭니다. #m은 매크로 인자의 이름을 문자열로 바꾸는 C 전처리기 기능입니다. ind+12 폭의 빈 문자열을 먼저 출력해 들여쓰기를 만듭니다. 표에 없는 비트 이름을 자동으로 알아내는 함수는 아닙니다.
 * state=5, 표의 mask가 1·2·4이면 5&1과 5&4만 참이라 두 이름을 출력합니다. size는 바이트 수가 아니라 설명 항목 수이며 호출부가 ARRAY_SIZE로 전달합니다.
 */
void irq_debug_show_bits(struct seq_file *m, int ind, unsigned int state,
			 const struct irq_bit_descr *sd, int size)
{
	int i;

	for (i = 0; i < size; i++, sd++) {
		if (state & sd->mask)
			seq_printf(m, "%*s%s\n", ind + 12, "", sd->name);
	}
}

#ifdef CONFIG_SMP
static void irq_debug_show_masks(struct seq_file *m, struct irq_desc *desc)
{
	struct irq_data *data = irq_desc_get_irq_data(desc);
	const struct cpumask *msk;

	msk = irq_data_get_affinity_mask(data);
	seq_printf(m, "affinity: %*pbl\n", cpumask_pr_args(msk));
#ifdef CONFIG_GENERIC_IRQ_EFFECTIVE_AFF_MASK
	msk = irq_data_get_effective_affinity_mask(data);
	seq_printf(m, "effectiv: %*pbl\n", cpumask_pr_args(msk));
#endif
#ifdef CONFIG_GENERIC_PENDING_IRQ
	msk = desc->pending_mask;
	seq_printf(m, "pending:  %*pbl\n", cpumask_pr_args(msk));

/* 학습 해설
 * IRQ 상태 표 네 종류: chip 기능과 현재 실행 상태 구별
 * IRQ 디버그 화면에 여러 16진수가 나오는 이유는 모두 같은 정보를 반복하는 것이 아니라 서로 다른 종류의 상태를 보여 주기 때문입니다.
 * irqchip_flags는 chip의 타입 변경 마스킹·EOI 처리·절전 마스킹·온라인/오프라인·wake 생략·oneshot·thread EOI·level MSI·NMI·절전 wake enable·immutable 기능을 이름으로 표시합니다. irqdata_states는 트리거, 활성화·시작·disable·mask·진행, CPU 배치와 이동, 관리형 상태, vCPU 전달, 깨우기, 문맥 강제 및 재전달 상태를 나열합니다. irqdesc_states는 probe·request·thread·autoenable 금지와 nested·per-CPU 식별·polled·unlazy·hidden 설정을, irqdesc_istates는 탐색·이상 중단·폴링·oneshot·replay·waiting·pending·절전·NMI 내부 상태를 담습니다.
 * IRQCHIP_MASK_ON_SUSPEND는 chip이 요구하는 처리 방식이고 IRQS_SUSPENDED는 현재 descriptor의 내부 상태라는 차이를 찾아보세요. 앞서 읽은 pm.c와 spurious.c가 어느 상태를 바꿨는지 출력 표에 연결하세요.
 */
static int irq_debug_show(struct seq_file *m, void *p)
{
	struct irq_desc *desc = m->private;
	struct irq_data *data;

	raw_spin_lock_irq(&desc->lock);
	data = irq_desc_get_irq_data(desc);
	seq_printf(m, "handler:  %ps\n", desc->handle_irq);
	seq_printf(m, "device:   %s\n", desc->dev_name);
	seq_printf(m, "status:   0x%08x\n", desc->status_use_accessors);
	irq_debug_show_bits(m, 0, desc->status_use_accessors, irqdesc_states,
			    ARRAY_SIZE(irqdesc_states));
	seq_printf(m, "istate:   0x%08x\n", desc->istate);
	irq_debug_show_bits(m, 0, desc->istate, irqdesc_istates,
			    ARRAY_SIZE(irqdesc_istates));
	seq_printf(m, "ddepth:   %u\n", desc->depth);
	seq_printf(m, "wdepth:   %u\n", desc->wake_depth);
	seq_printf(m, "dstate:   0x%08x\n", irqd_get(data));
	irq_debug_show_bits(m, 0, irqd_get(data), irqdata_states,
			    ARRAY_SIZE(irqdata_states));
	seq_printf(m, "node:     %d\n", irq_data_get_node(data));
	irq_debug_show_masks(m, desc);
	irq_debug_show_data(m, data, 0);
	raw_spin_unlock_irq(&desc->lock);
	return 0;
}

/* 학습 해설
 * IRQ affinity 출력: 빌드 설정에 따라 달라지는 세 집합
 * 요청한 CPU, 실제 배치된 CPU, 아직 적용을 기다리는 CPU 집합을 함께 보면 IRQ 이동이 어떤 단계에 있는지 이해할 수 있습니다.
 * CONFIG_SMP에서는 일반 affinity를 affinity 줄에 출력합니다. CONFIG_GENERIC_IRQ_EFFECTIVE_AFF_MASK가 있으면 실제 집합을 effectiv 줄에, CONFIG_GENERIC_PENDING_IRQ가 있으면 pending_mask를 pending 줄에 출력합니다. %*pbl과 cpumask_pr_args는 CPU 비트 집합을 목록 형태로 출력하는 커널 형식입니다. SMP가 아닌 빌드에서는 같은 이름의 함수가 빈 본문이어서 이 정보들을 출력하지 않습니다. 줄의 부재와 빈 집합의 출력을 같은 상태로 해석하면 안 됩니다.
 * 요청 {1,2}, 실제 {2}, 대기 {3}을 각각 다른 줄에 적으세요. effective 지원 설정을 끈 경우에는 실제 집합이 비어서가 아니라 해당 출력 코드가 컴파일되지 않은 것일 수 있습니다.
 */
static void irq_debug_show_masks(struct seq_file *m, struct irq_desc *desc)
{
	struct irq_data *data = irq_desc_get_irq_data(desc);
	const struct cpumask *msk;

	msk = irq_data_get_affinity_mask(data);
	seq_printf(m, "affinity: %*pbl\n", cpumask_pr_args(msk));
#ifdef CONFIG_GENERIC_IRQ_EFFECTIVE_AFF_MASK
	msk = irq_data_get_effective_affinity_mask(data);
	seq_printf(m, "effectiv: %*pbl\n", cpumask_pr_args(msk));
#endif
#ifdef CONFIG_GENERIC_PENDING_IRQ
	msk = desc->pending_mask;
	seq_printf(m, "pending:  %*pbl\n", cpumask_pr_args(msk));
#endif
}
#else
static void irq_debug_show_masks(struct seq_file *m, struct irq_desc *desc) { }
#endif

static const struct irq_bit_descr irqchip_flags[] = {
	BIT_MASK_DESCR(IRQCHIP_SET_TYPE_MASKED),
	BIT_MASK_DESCR(IRQCHIP_EOI_IF_HANDLED),
	BIT_MASK_DESCR(IRQCHIP_MASK_ON_SUSPEND),
	BIT_MASK_DESCR(IRQCHIP_ONOFFLINE_ENABLED),
	BIT_MASK_DESCR(IRQCHIP_SKIP_SET_WAKE),

/* 학습 해설
 * IRQ chip 출력: 선택적 콜백과 기본 이름의 분기
 * 인터럽트 컨트롤러마다 표시할 세부 이름이 다를 수 있어 공통 출력 코드는 기본 이름과 컨트롤러 전용 출력 함수를 함께 지원합니다.
 * irq_debug_show_chip은 data->chip이 없으면 chip: None을 출력하고 반환합니다. chip이 있으면 irq_print_chip 콜백이 있는지 확인해 호출하고, 없으면 chip->name을 출력합니다. 그 뒤 flags 원시값을 16진수로 출력하고 irqchip_flags 표로 이름을 풉니다. 선택적 콜백을 쓰더라도 공통 flags 출력은 이어집니다. 콜백은 IRQ를 처리하는 handler가 아니라 현재 seq_file에 진단 문자열을 출력하기 위한 인터페이스입니다.
 * chip 없음, chip은 있으나 출력 콜백 없음, 출력 콜백 있음의 세 경로를 그리세요. 각 경로에서 chip 이름과 flags 줄이 어디까지 나오는지 비교하세요.
 */
irq_debug_show_chip(struct seq_file *m, struct irq_data *data, int ind)
{
	struct irq_chip *chip = data->chip;

	if (!chip) {
		seq_printf(m, "chip: None\n");
		return;
	}
	seq_printf(m, "%*schip:    ", ind, "");
	if (chip->irq_print_chip)
		chip->irq_print_chip(data, m);
	else
		seq_printf(m, "%s", chip->name);
	seq_printf(m, "\n%*sflags:   0x%lx\n", ind + 1, "", chip->flags);
	irq_debug_show_bits(m, ind, chip->flags, irqchip_flags,
			    ARRAY_SIZE(irqchip_flags));
}

static void
irq_debug_show_data(struct seq_file *m, struct irq_data *data, int ind)
{
	seq_printf(m, "%*sdomain:  %s\n", ind, "",
		   data->domain ? data->domain->name : "");
	seq_printf(m, "%*shwirq:   0x%lx\n", ind + 1, "", data->hwirq);
	irq_debug_show_chip(m, data, ind + 1);
	if (data->domain && data->domain->ops && data->domain->ops->debug_show)

/* 학습 해설
 * IRQ domain 계층 출력: 부모 포인터를 따라가는 재귀
 * 하나의 Linux IRQ가 여러 컨트롤러 계층을 통과할 수 있어 최상위 번호만 보여 주면 실제 전달 구조를 이해하기 어렵습니다.
 * irq_debug_show_data는 domain 이름과 hwirq를 출력하고 chip 정보를 호출합니다. domain·ops·debug_show가 모두 있으면 도메인 전용 콜백도 호출합니다. CONFIG_IRQ_DOMAIN_HIERARCHY에서는 parent_data가 없으면 반환하고, 있으면 parent 표기 뒤 부모를 같은 함수에 넘기며 ind를 4 늘립니다. 설정이 꺼지면 부모 순회 코드는 없습니다. Linux IRQ 번호와 각 계층의 hwirq는 역할이 다르며 부모에서도 새로운 하드웨어 번호를 출력합니다.
 * 자식 A→부모 B→부모 없음의 구조를 그리고 A와 B의 domain·hwirq·chip이 차례로 출력되는 것을 따라가세요. ind 증가가 트리 구조를 눈으로 구분하는 들여쓰기를 만듭니다.
 */
irq_debug_show_data(struct seq_file *m, struct irq_data *data, int ind)
{
	seq_printf(m, "%*sdomain:  %s\n", ind, "",
		   data->domain ? data->domain->name : "");
	seq_printf(m, "%*shwirq:   0x%lx\n", ind + 1, "", data->hwirq);
	irq_debug_show_chip(m, data, ind + 1);
	if (data->domain && data->domain->ops && data->domain->ops->debug_show)
		data->domain->ops->debug_show(m, NULL, data, ind + 1);
#ifdef	CONFIG_IRQ_DOMAIN_HIERARCHY
	if (!data->parent_data)
		return;
	seq_printf(m, "%*sparent:\n", ind + 1, "");
	irq_debug_show_data(m, data->parent_data, ind + 4);
#endif
}

static const struct irq_bit_descr irqdata_states[] = {
	BIT_MASK_DESCR(IRQ_TYPE_EDGE_RISING),
	BIT_MASK_DESCR(IRQ_TYPE_EDGE_FALLING),
	BIT_MASK_DESCR(IRQ_TYPE_LEVEL_HIGH),
	BIT_MASK_DESCR(IRQ_TYPE_LEVEL_LOW),
	BIT_MASK_DESCR(IRQD_LEVEL),

	BIT_MASK_DESCR(IRQD_ACTIVATED),
	BIT_MASK_DESCR(IRQD_IRQ_STARTED),
	BIT_MASK_DESCR(IRQD_IRQ_DISABLED),

/* 학습 해설
 * IRQ 진단 파일 읽기: single_open과 seq_file 연결
 * 커널 상태를 파일처럼 읽게 하려면 파일 open·read·seek·close 동작과 실제 텍스트 생성 함수를 연결해야 합니다.
 * irq_debug_open은 single_open(file,irq_debug_show,inode->i_private)의 결과를 그대로 반환합니다. dfs_irq_ops는 open을 이 함수에, read를 seq_read, llseek를 seq_lseek, release를 single_release, write를 irq_debug_write에 연결합니다. irq_debug_show의 m->private에는 전달된 descriptor가 연결됩니다. show 함수는 raw_spin_lock_irq로 descriptor를 보호하며 handler·device·status·istate·disable depth·wake depth·irq_data 상태·NUMA node·mask·domain 정보를 출력한 뒤 잠금을 풀고 0입니다.
 * debugfs_create_file에 넘긴 desc→inode private→single_open의 private→show의 m->private 경로를 화살표로 이어 보세요. single_open의 오류가 wrapper에서 다른 값으로 바뀌지 않고 전달되는 것도 확인하세요.
 */
static int irq_debug_open(struct inode *inode, struct file *file)
{
	return single_open(file, irq_debug_show, inode->i_private);
}

static ssize_t irq_debug_write(struct file *file, const char __user *user_buf,
			       size_t count, loff_t *ppos)
{
	struct irq_desc *desc = file_inode(file)->i_private;
	char buf[8] = { 0, };
	size_t size;

	size = min(sizeof(buf) - 1, count);
	if (copy_from_user(buf, user_buf, size))
		return -EFAULT;

	if (!strncmp(buf, "trigger", size)) {
		int err = irq_inject_interrupt(irq_desc_get_irq(desc));

		return err ? err : count;
	}

	return count;
}

static const struct file_operations dfs_irq_ops = {

/* 학습 해설
 * IRQ debugfs 입력 길이: trigger 전체 단어만 검사하는 코드가 아니다
 * 사용자 입력을 제한된 버퍼로 받아 비교할 때 비교 길이를 어떻게 고르는지에 따라 짧은 접두어나 긴 문자열도 명령으로 인정될 수 있습니다.
 * irq_debug_write는 8바이트 buf를 0으로 초기화하고 min(7,count)만큼 copy_from_user합니다. 복사가 완전하지 않으면 -EFAULT입니다. strncmp(buf,"trigger",size)가 0이면 irq_inject_interrupt를 호출하고 오류면 그 오류, 성공이면 원래 count를 반환합니다. 일치하지 않아도 count를 반환합니다. 비교 길이가 size이므로 "t"나 "tri" 같은 접두어도 일치하고, 7바이트보다 긴 "triggerXYZ"도 앞 7바이트가 같아 일치합니다. 이 함수에 count=0이 전달돼 도달하면 길이 0 비교도 일치합니다. ppos는 사용하지 않습니다.
 * 이 단원은 입력 비교 코드를 분석하는 문제입니다. 실제 IRQ를 주입하지 말고 표에서 count와 size, 비교할 앞부분, 반환 경로를 계산하세요. "x"는 비교 불일치지만 성공한 쓰기처럼 count를 반환한다는 차이를 확인하세요.
 */
static ssize_t irq_debug_write(struct file *file, const char __user *user_buf,
			       size_t count, loff_t *ppos)
{
	struct irq_desc *desc = file_inode(file)->i_private;
	char buf[8] = { 0, };
	size_t size;

	size = min(sizeof(buf) - 1, count);
	if (copy_from_user(buf, user_buf, size))
		return -EFAULT;

	if (!strncmp(buf, "trigger", size)) {
		int err = irq_inject_interrupt(irq_desc_get_irq(desc));

		return err ? err : count;
	}

	return count;
}

static const struct file_operations dfs_irq_ops = {
	.open		= irq_debug_open,
	.write		= irq_debug_write,
	.read		= seq_read,
	.llseek		= seq_lseek,
	.release	= single_release,

/* 학습 해설
 * IRQ 장치 이름 복사: 문자열 소유권과 할당 실패
 * 장치가 가진 이름 포인터를 그대로 오래 보관하면 원래 객체의 수명에 영향을 받으므로 진단용 이름을 별도 문자열로 복사하는 경로가 있습니다.
 * irq_debugfs_copy_devname은 IRQ 번호로 descriptor를 찾고 dev_name(dev)를 얻습니다. 이름이 있으면 kstrdup(name,GFP_KERNEL) 결과를 desc->dev_name에 저장합니다. kstrdup은 새 메모리를 할당해 문자열을 복사하며 실패하면 NULL일 수 있지만 이 함수는 오류를 반환하지 않습니다. 이름이 없으면 기존 값을 건드리지 않습니다. descriptor NULL 검사, 기존 문자열 해제, 반복 호출을 위한 교체 처리는 이 함수에 없으므로 유효한 객체와 올바른 호출 수명을 전제로 읽어야 합니다.
 * 원래 장치 이름 문자열과 복사된 문자열을 서로 다른 메모리 상자로 그리세요. internals.h의 irq_remove_debugfs_entry가 debugfs_remove와 kfree(desc->dev_name)를 수행하는 정리 연결을 함께 확인하세요.
 */
void irq_debugfs_copy_devname(int irq, struct device *dev)
{
	struct irq_desc *desc = irq_to_desc(irq);
	const char *name = dev_name(dev);

	if (name)
		desc->dev_name = kstrdup(name, GFP_KERNEL);
}

void irq_add_debugfs_entry(unsigned int irq, struct irq_desc *desc)
{
	char name [10];

	if (!irq_dir || !desc || desc->debugfs_file)
		return;

	sprintf(name, "%d", irq);
	desc->debugfs_file = debugfs_create_file(name, 0644, irq_dir, desc,
						 &dfs_irq_ops);
}

static int __init irq_debugfs_init(void)
{
	struct dentry *root_dir;
	int irq;

/* 학습 해설
 * IRQ debugfs 생성: 초기 순회와 나중 등록의 공통 helper
 * 이미 존재하는 IRQ와 나중에 등록되는 IRQ를 같은 이름 규칙으로 노출하려면 디렉터리 초기화와 항목 생성 단계를 나누어 연결해야 합니다.
 * irq_add_debugfs_entry는 irq_dir이 없거나 desc가 없거나 이미 debugfs_file이 있으면 반환합니다. 아니면 char name[10]에 IRQ 번호를 sprintf의 %d로 만들고 0644 파일을 생성하며 private 데이터로 desc, 연산 표로 dfs_irq_ops를 넘깁니다. irq_debugfs_init은 최상위 irq 디렉터리와 도메인 진단 항목, 그 아래 irqs 디렉터리를 만든 뒤 sparse 잠금 안에서 모든 active IRQ에 같은 helper를 호출합니다. __initcall이 초기화 함수를 부팅 경로에 연결하며 init의 반환은 항상 0입니다.
 * irq/irqs/번호 형태의 상대 구조를 그리세요. 생성 helper가 반환한 dentry를 descriptor에 저장하는 이유와 이미 파일이 있는 항목을 건너뛰는 조건을 찾으세요. 실제 사용 경로는 debugfs를 마운트한 위치에 따라 달라집니다.
 */
void irq_add_debugfs_entry(unsigned int irq, struct irq_desc *desc)
{
	char name [10];

	if (!irq_dir || !desc || desc->debugfs_file)
		return;

	sprintf(name, "%d", irq);
	desc->debugfs_file = debugfs_create_file(name, 0644, irq_dir, desc,
						 &dfs_irq_ops);
}

static int __init irq_debugfs_init(void)
{
	struct dentry *root_dir;
	int irq;

	root_dir = debugfs_create_dir("irq", NULL);

	irq_domain_debugfs_init(root_dir);

	irq_dir = debugfs_create_dir("irqs", root_dir);

	irq_lock_sparse();
	for_each_active_irq(irq)
		irq_add_debugfs_entry(irq, irq_to_desc(irq));

/* 학습 해설
 * 관리형 threaded IRQ 등록: 정리 기록을 먼저 확보하는 이유
 * 실제 IRQ 등록에는 성공했는데 자동 해제 기록을 만들 메모리가 없다면 장치 분리 때 정리할 근거를 잃을 수 있어 준비 순서가 중요합니다.
 * devm_request_threaded_irq는 먼저 devres_alloc으로 devm_irq_release 콜백을 가진 기록을 GFP_KERNEL로 할당합니다. 실패하면 -ENOMEM으로 끝내고 IRQ 등록은 시도하지 않습니다. devname이 NULL이면 dev_name(dev)를 대신 사용합니다. request_threaded_irq를 호출해 반환이 0이 아니면 아직 등록 목록에 넣지 않은 기록만 devres_free하고 해당 오류를 반환합니다. 성공하면 irq와 dev_id를 채워 devres_add로 장치에 연결한 뒤 0을 반환합니다.
 * 기록 할당 실패, IRQ 요청 실패, 둘 다 성공의 세 경로에서 기록과 IRQ 등록이 각각 존재하는지 표로 그리세요. 실패 시 devres_free가 실제 IRQ를 해제하는 release 콜백 호출과 같은 것이 아님을 구별하세요.
 */
int devm_request_threaded_irq(struct device *dev, unsigned int irq,
			      irq_handler_t handler, irq_handler_t thread_fn,
			      unsigned long irqflags, const char *devname,
			      void *dev_id)
{
	struct irq_devres *dr;
	int rc;

	dr = devres_alloc(devm_irq_release, sizeof(struct irq_devres),
			  GFP_KERNEL);
	if (!dr)
		return -ENOMEM;

	if (!devname)
		devname = dev_name(dev);

	rc = request_threaded_irq(irq, handler, thread_fn, irqflags, devname,
				  dev_id);
	if (rc) {
		devres_free(dr);
		return rc;
	}

	dr->irq = irq;
	dr->dev_id = dev_id;
	devres_add(dev, dr);

/* 학습 해설
 * 문맥 자동 선택 IRQ 등록: 양수도 성공일 수 있다
 * 어떤 API는 성공할 때 실행 문맥의 종류를 알려 주므로 0이 아닌 값을 모두 실패라고 검사하면 정상 등록을 잘못 처리합니다.
 * devm_request_any_context_irq도 기록을 먼저 할당하고 NULL devname을 장치 이름으로 대체합니다. request_any_context_irq 결과는 rc < 0일 때만 실패로 처리합니다. 0 또는 양수이면 기록을 채워 장치에 추가하고 rc를 그대로 반환합니다. interrupt.h의 IRQC_IS_HARDIRQ는 0이고 IRQC_IS_NESTED는 1입니다. 일반 threaded wrapper의 if(rc)와 달리 이 API는 비음수 문맥 결과를 보존해야 합니다.
 * rc=-ENOMEM, rc=0, rc=1을 세 칸에 놓고 자원 기록을 목록에 넣는 경우를 표시하세요. rc=1을 실패로 오인하면 실제 등록은 살아 있는데 호출자가 실패 정리를 시작할 수 있습니다.
 */
int devm_request_any_context_irq(struct device *dev, unsigned int irq,
			      irq_handler_t handler, unsigned long irqflags,
			      const char *devname, void *dev_id)
{
	struct irq_devres *dr;
	int rc;

	dr = devres_alloc(devm_irq_release, sizeof(struct irq_devres),
			  GFP_KERNEL);
	if (!dr)
		return -ENOMEM;

	if (!devname)
		devname = dev_name(dev);

	rc = request_any_context_irq(irq, handler, irqflags, devname, dev_id);
	if (rc < 0) {
		devres_free(dr);
		return rc;
	}

	dr->irq = irq;
	dr->dev_id = dev_id;
	devres_add(dev, dr);

	return rc;

/* 학습 해설
 * 관리 IRQ를 먼저 해제하기: devres 기록과 실제 IRQ를 따로 제거
 * 자동 해제로 등록한 IRQ를 수동으로 먼저 정리할 때 실제 IRQ만 해제하면 장치 분리 시 같은 기록으로 다시 해제하려 할 수 있습니다.
 * devm_free_irq는 irq와 dev_id로 match_data를 만들고 devres_destroy에 장치·release 종류·match 함수를 넘깁니다. devres_destroy는 일치 기록을 목록에서 제거하고 기록 메모리를 해제하지만 release 콜백은 호출하지 않습니다. 그래서 이어 free_irq를 직접 호출합니다. 기록을 못 찾으면 WARN_ON 조건이 되지만 이 함수 본문은 그것을 실패 반환이나 free_irq 생략 조건으로 쓰지 않습니다. 정상 계약은 devm으로 등록한 IRQ를 같은 장치와 cookie로 해제하는 것입니다.
 * 자동 해제 예정 기록 있음→destroy로 기록 제거→free_irq로 실제 등록 제거 순서를 그리세요. free_irq만 호출하는 것과 devres_release를 사용해 콜백까지 실행하는 것의 차이를 비교하세요.
 */
void devm_free_irq(struct device *dev, unsigned int irq, void *dev_id)
{
	struct irq_devres match_data = { irq, dev_id };

	WARN_ON(devres_destroy(dev, devm_irq_release, devm_irq_match,
			       &match_data));
	free_irq(irq, dev_id);
}
EXPORT_SYMBOL(devm_free_irq);

struct irq_desc_devres {
	unsigned int from;
	unsigned int cnt;
};

static void devm_irq_desc_release(struct device *dev, void *res)
{
	struct irq_desc_devres *this = res;

	irq_free_descs(this->from, this->cnt);
}

/**
 * __devm_irq_alloc_descs - Allocate and initialize a range of irq descriptors
 *			    for a managed device
 * @dev:	Device to allocate the descriptors for
 * @irq:	Allocate for specific irq number if irq >= 0
 * @from:	Start the search from this irq number
 * @cnt:	Number of consecutive irqs to allocate
 * @node:	Preferred node on which the irq descriptor should be allocated
 * @owner:	Owning module (can be NULL)
 * @affinity:	Optional pointer to an irq_affinity_desc array of size @cnt
 *		which hints where the irq descriptors should be allocated
 *		and which default affinities to use
 *
 * Returns the first irq number or error code.
 *
 * Note: Use the provided wrappers (devm_irq_alloc_desc*) for simplicity.
 */

/* 학습 해설
 * IRQ descriptor 범위 관리: 요청 시작값과 실제 배정값 구별
 * 빈 IRQ 번호 범위를 찾아 할당할 때 검색 시작 번호와 실제 할당된 시작 번호가 다를 수 있어 해제 기록에는 결과를 저장해야 합니다.
 * struct irq_desc_devres는 from과 cnt를 저장합니다. __devm_irq_alloc_descs는 기록을 먼저 할당한 뒤 __irq_alloc_descs에 지정 irq·검색 from·연속 개수·NUMA node·owner·affinity를 넘깁니다. base < 0이면 기록을 free하고 오류를 반환합니다. 성공하면 dr->from=base와 dr->cnt=cnt를 저장해 장치에 연결합니다. devm_irq_desc_release는 저장된 시작과 개수로 irq_free_descs를 호출합니다. 성공값 0도 가능한 비음수 결과이므로 if(base)로 오류를 판단하지 않습니다.
 * 검색 from=20, 실제 base=24, cnt=3인 예에서 관리 범위는 24·25·26입니다. from=20을 그대로 기록하면 다른 범위를 해제할 수 있다는 이유를 적으세요.
 */
int __devm_irq_alloc_descs(struct device *dev, int irq, unsigned int from,
			   unsigned int cnt, int node, struct module *owner,
			   const struct irq_affinity_desc *affinity)
{
	struct irq_desc_devres *dr;
	int base;

	dr = devres_alloc(devm_irq_desc_release, sizeof(*dr), GFP_KERNEL);
	if (!dr)
		return -ENOMEM;

	base = __irq_alloc_descs(irq, from, cnt, node, owner, affinity);
	if (base < 0) {
		devres_free(dr);
		return base;
	}

	dr->from = base;
	dr->cnt = cnt;
	devres_add(dev, dr);

	return base;
}
EXPORT_SYMBOL_GPL(__devm_irq_alloc_descs);

#ifdef CONFIG_GENERIC_IRQ_CHIP

/* 학습 해설
 * generic IRQ chip 할당: 가변 길이 배열의 크기까지 계산하기
 * generic chip 하나에 여러 irq_chip_type을 붙일 수 있으므로 고정 구조체 크기만 할당하면 뒤에 이어지는 타입 배열 공간이 부족할 수 있습니다.
 * CONFIG_GENERIC_IRQ_CHIP에서 devm_irq_alloc_generic_chip은 struct_size(gc,chip_types,num_ct)로 구조체와 가변 길이 배열을 포함한 크기를 계산해 devm_kzalloc합니다. 성공 포인터일 때만 irq_init_generic_chip에 이름·타입 수·IRQ 시작·레지스터 가상 주소·기본 flow handler를 넘깁니다. 실패는 NULL이고 ERR_PTR이 아닙니다. devm_kzalloc은 메모리의 자동 해제를 연결하지만 이 함수만으로 IRQ 범위의 설정까지 완료되는 것은 아닙니다.
 * 고정 부분을 H바이트, 타입 요소를 T바이트라고 두고 요청 크기가 H+num_ct×T를 반영해야 하는 이유를 그림으로 나타내세요. 구체적인 H와 T는 대상 빌드의 구조체 배치에 따라 다릅니다.
 */
devm_irq_alloc_generic_chip(struct device *dev, const char *name, int num_ct,
			    unsigned int irq_base, void __iomem *reg_base,
			    irq_flow_handler_t handler)
{
	struct irq_chip_generic *gc;

	gc = devm_kzalloc(dev, struct_size(gc, chip_types, num_ct), GFP_KERNEL);
	if (gc)
		irq_init_generic_chip(gc, name, num_ct,
				      irq_base, reg_base, handler);

	return gc;
}
EXPORT_SYMBOL_GPL(devm_irq_alloc_generic_chip);

struct irq_generic_chip_devres {
	struct irq_chip_generic *gc;
	u32 msk;
	unsigned int clr;
	unsigned int set;
};

static void devm_irq_remove_generic_chip(struct device *dev, void *res)
{
	struct irq_generic_chip_devres *this = res;

/* 학습 해설
 * generic IRQ 설정 기록: 비트 집합과 해제 인자 보관
 * generic chip으로 설정한 여러 IRQ를 나중에 제거하려면 chip 포인터뿐 아니라 어느 IRQ와 어떤 상태 비트를 다뤘는지 기억해야 합니다.
 * struct irq_generic_chip_devres는 gc, u32 msk, clr, set을 저장합니다. setup wrapper는 devm_irq_remove_generic_chip 콜백의 기록을 먼저 할당하고 실패하면 -ENOMEM입니다. irq_setup_generic_chip을 호출한 뒤 네 값을 기록해 devres_add하고 0입니다. remove 콜백은 저장된 값을 그대로 irq_remove_generic_chip에 전달합니다. u32 msk의 비트는 gc->irq_base 기준의 최대 32개 위치를 나타냅니다. 이 wrapper는 이전 하드웨어 레지스터 상태 전체를 스냅샷으로 저장하지 않습니다.
 * irq_base=100, msk=5라면 비트 0과 2에 해당하는 100·102를 선택합니다. clr·set은 IRQ 상태 비트 인자이며 msk의 상대 IRQ 선택과 다른 목적이라는 것을 표시하세요.
 */
int devm_irq_setup_generic_chip(struct device *dev, struct irq_chip_generic *gc,
				u32 msk, enum irq_gc_flags flags,
				unsigned int clr, unsigned int set)
{
	struct irq_generic_chip_devres *dr;

	dr = devres_alloc(devm_irq_remove_generic_chip,
			  sizeof(*dr), GFP_KERNEL);
	if (!dr)
		return -ENOMEM;

	irq_setup_generic_chip(gc, msk, flags, clr, set);

	dr->gc = gc;
	dr->msk = msk;
	dr->clr = clr;
	dr->set = set;
	devres_add(dev, dr);

	return 0;
}
EXPORT_SYMBOL_GPL(devm_irq_setup_generic_chip);
#endif /* CONFIG_GENERIC_IRQ_CHIP */

#ifdef CONFIG_IRQ_DOMAIN
static void devm_irq_domain_remove(struct device *dev, void *res)

/* 학습 해설
 * 관리 IRQ domain 생성: 포인터를 보관하는 포인터 기록
 * IRQ domain을 장치 수명에 연결하려면 생성된 domain 객체를 나중 제거 콜백에서 다시 찾을 수 있도록 포인터 자체를 기록해야 합니다.
 * CONFIG_IRQ_DOMAIN에서 devm_irq_domain_instantiate의 dr은 struct irq_domain **입니다. devres_alloc에는 sizeof(*dr)를 넘겨 domain 포인터 하나의 저장 공간을 만듭니다. 기록 할당 실패는 ERR_PTR(-ENOMEM)입니다. irq_domain_instantiate가 오류 포인터가 아니면 *dr=domain으로 저장하고 장치에 추가합니다. 오류 포인터이면 기록만 free합니다. 반환은 하위 domain 결과 그대로이며 devm_irq_domain_remove는 저장된 포인터를 역참조해 irq_domain_remove를 호출합니다.
 * dr→포인터 저장 칸→domain 객체의 두 화살표를 그리세요. sizeof(*dr)는 domain 구조체 전체 크기가 아니라 domain 포인터 크기라는 것을 C의 타입과 연결해 읽으세요.
 */
struct irq_domain *devm_irq_domain_instantiate(struct device *dev,
					       const struct irq_domain_info *info)
{
	struct irq_domain *domain;
	struct irq_domain **dr;

	dr = devres_alloc(devm_irq_domain_remove, sizeof(*dr), GFP_KERNEL);
	if (!dr)
		return ERR_PTR(-ENOMEM);

	domain = irq_domain_instantiate(info);
	if (!IS_ERR(domain)) {
		*dr = domain;
		devres_add(dev, dr);
	} else {
		devres_free(dr);
	}

	return domain;
}
EXPORT_SYMBOL_GPL(devm_irq_domain_instantiate);
#endif /* CONFIG_IRQ_DOMAIN */

/* 학습 해설
 * IRQ affinity 예약 벡터: 앞뒤 예약을 뺀 뒤 남은 수 계산
 * 장치의 모든 인터럽트가 데이터 큐 처리용은 아닐 수 있어 앞뒤의 특별한 벡터를 예약하고 남은 벡터에만 CPU 분산 정책을 적용합니다.
 * irq_create_affinity_masks는 nvecs가 pre_vectors+post_vectors보다 클 때만 둘을 빼서 affvecs를 계산하고 아니면 0으로 둡니다. calc_sets가 없으면 default_calc_sets를 설치한 뒤, affvecs가 0이어도 calc_sets를 호출합니다. 드라이버가 벡터 부족 상태에 맞게 세트 구성을 조정할 기회를 주기 때문입니다. 이후 nr_sets가 IRQ_AFFINITY_MAX_SETS보다 크면 경고 후 NULL이고, affvecs가 0이어도 NULL입니다. 이 NULL은 반드시 메모리 부족만 뜻하지 않습니다.
