	 * Simple invocations do not provide a calc_sets() callback. Install
	 * the generic one.
	 */
	if (!affd->calc_sets)
		affd->calc_sets = default_calc_sets;

	/* Recalculate the sets */
	affd->calc_sets(affd, affvecs);

/* 학습 해설
 * 기본 IRQ 세트 계산: 함수 포인터 설치는 설정 객체를 바꾼다
