 * 초기 calc_sets=NULL, nr_sets=3인 객체를 넘긴 뒤 생성 경로에서 어떤 필드가 바뀌는지 적으세요. 콜백 내부의 0 크기 기록과 생성 함수의 이후 NULL 반환을 나누어 읽으세요.
 */
static void default_calc_sets(struct irq_affinity *affd, unsigned int affvecs)
{
	affd->nr_sets = 1;
	affd->set_size[0] = affvecs;
}

