	affd->calc_sets(affd, affvecs);

/* 학습 해설
 * IRQ 벡터 수 계산: 가능한 CPU 수·최대치·예약분을 함께 보기
 * 벡터가 너무 많으면 자원을 낭비할 수 있고 너무 적으면 큐 분산이 제한되므로 예약분과 CPU 후보 수를 바탕으로 요청 수를 계산합니다.
 * irq_calc_affinity_vectors는 resv=pre+post가 minvec보다 크면 0입니다. calc_sets 포인터가 있으면 set_vecs=maxvec-resv를 사용하고, 없으면 cpus_read_lock 안에서 cpu_possible_mask의 켜진 비트 수를 센 뒤 풉니다. 반환은 resv+min(set_vecs,maxvec-resv)입니다. possible CPU 수는 현재 온라인 CPU 수와 같다는 보장이 없습니다. 이 함수는 minvec로 최종 결과를 다시 올려 맞추는 max 연산을 하지 않으므로 입력 관계에 따라 계산 결과가 minvec보다 작을 수도 있습니다.
 * min=2, max=10, pre=1, post=1, 가능한 CPU=4, 콜백 없음이면 2+min(4,8)=6입니다. 콜백이 있으면 10입니다. min=8, 같은 나머지 조건이면 이 코드의 결과는 여전히 6이라는 점을 계산하세요. 유효한 min≤max 및 오버플로 없는 입력 계약도 필요합니다.
 */
unsigned int irq_calc_affinity_vectors(unsigned int minvec, unsigned int maxvec,
				       const struct irq_affinity *affd)
{
	unsigned int resv = affd->pre_vectors + affd->post_vectors;
	unsigned int set_vecs;

	if (resv > minvec)
		return 0;

	if (affd->calc_sets) {
		set_vecs = maxvec - resv;
	} else {
		cpus_read_lock();
		set_vecs = cpumask_weight(cpu_possible_mask);
		cpus_read_unlock();
	}

	return resv + min(set_vecs, maxvec - resv);
}

/* 학습 해설
 * IRQ domain 식별: 하드웨어 번호와 Linux 번호의 이름 공간
 * 서로 다른 컨트롤러가 각각 하드웨어 IRQ 5번을 사용할 수 있으므로 숫자 하나만으로 시스템 전체의 인터럽트를 구별할 수 없습니다.
 * IRQ domain은 컨트롤러 쪽 hwirq 번호와 Linux가 관리하는 virq 번호의 대응을 다루는 객체입니다. fwnode는 어느 컨트롤러의 domain인지 찾는 식별 단서입니다. 이 파일의 irqchip_fwid는 fwnode_handle을 내부 멤버로 포함하고 type·name·물리 주소 포인터를 함께 둡니다. irqchip_fwnode_get_name은 container_of로 포함 객체를 찾아 name을 반환합니다. irqchip_fwnode_ops의 get_name 콜백이 이 함수에 연결됩니다.
 * 컨트롤러 A의 hwirq 5→virq 40, B의 hwirq 5→virq 91을 그리세요. 두 5가 충돌하지 않는 이유와 이름 조회가 새 문자열 복사가 아니라 저장된 포인터 반환이라는 점을 적으세요.
 */
static const char *irqchip_fwnode_get_name(const struct fwnode_handle *fwnode)
{
	struct irqchip_fwid *fwid = container_of(fwnode, struct irqchip_fwid, fwnode);

	return fwid->name;
}

const struct fwnode_operations irqchip_fwnode_ops = {
	.get_name = irqchip_fwnode_get_name,
};
EXPORT_SYMBOL_GPL(irqchip_fwnode_ops);

/**
 * __irq_domain_alloc_fwnode - Allocate a fwnode_handle suitable for
 *                           identifying an irq domain
 * @type:	Type of irqchip_fwnode. See linux/irqdomain.h
 * @id:		Optional user provided id if name != NULL
 * @name:	Optional user provided domain name
 * @pa:		Optional user-provided physical address
 *
 * Allocate a struct irqchip_fwid, and return a pointer to the embedded
 * fwnode_handle (or NULL on failure).
 *
 * Note: The types IRQCHIP_FWNODE_NAMED and IRQCHIP_FWNODE_NAMED_ID are
 * solely to transport name information to irqdomain creation code. The
 * node is not stored. For other types the pointer is kept in the irq
 * domain struct.
 */

/* 학습 해설
 * IRQ fwnode 생성: 두 할당의 실패를 함께 정리하기
 * 식별 객체와 사람이 읽을 이름은 별도 메모리이므로 한쪽만 할당됐을 때도 남은 메모리를 정리해야 합니다.
 * __irq_domain_alloc_fwnode는 kzalloc으로 irqchip_fwid를 만들고 타입에 따라 kasprintf로 이름을 만듭니다. NAMED는 name, NAMED_ID는 name-id, 나머지는 irqchip@물리주소 형식입니다. fwid가 NULL이어도 이름 생성 단계는 실행되며 이후 둘 중 하나라도 실패하면 두 포인터 모두 kfree하고 NULL입니다. 성공하면 type·name·pa를 기록하고 fwnode_init으로 콜백을 연결한 뒤 내부 fwnode 주소를 반환합니다. pa는 포인터 값이 저장되며 가리키는 주소 값을 새 공간에 복제하지 않습니다.
 * 객체 성공·이름 실패, 객체 실패·이름 성공, 둘 다 성공을 표로 그리세요. 이름 있는 타입은 domain 이름 전달 용도이며 domain과 식별 노드의 수명을 무조건 같다고 가정하지 마세요.
 */
struct fwnode_handle *__irq_domain_alloc_fwnode(unsigned int type, int id,
						const char *name,
						phys_addr_t *pa)
{
	struct irqchip_fwid *fwid;
	char *n;

	fwid = kzalloc(sizeof(*fwid), GFP_KERNEL);

	switch (type) {
	case IRQCHIP_FWNODE_NAMED:
		n = kasprintf(GFP_KERNEL, "%s", name);
		break;
	case IRQCHIP_FWNODE_NAMED_ID:
		n = kasprintf(GFP_KERNEL, "%s-%d", name, id);
		break;
	default:
		n = kasprintf(GFP_KERNEL, "irqchip@%pa", pa);
		break;
	}

	if (!fwid || !n) {
		kfree(fwid);
		kfree(n);
		return NULL;
	}

/* 학습 해설
 * IRQ fwnode 해제: 타입 검사와 빌린 이름의 수명
 * 펌웨어 노드처럼 공통 타입으로 보이는 포인터라도 어떤 코드가 할당했는지에 따라 해제 방법이 다르므로 잘못된 free를 막아야 합니다.
 * irq_domain_free_fwnode는 NULL이면 반환하고 irqchip 종류가 아니면 WARN_ON 후 반환합니다. 맞는 타입이면 container_of로 바깥 객체를 찾아 name과 객체를 차례로 kfree합니다. domain의 전체 매핑을 해제하거나 목록에서 domain을 제거하는 함수가 아닙니다. domain 이름이 fwid->name을 빌려 쓰는 경로도 있으므로 어떤 타입에서 이름이 복사되고 어떤 타입에서 참조되는지 확인해 노드 수명을 정해야 합니다.
 * NAMED 타입에서 domain용 이름 복사본을 만든 경우와 기본 타입·BUS_ANY에서 원래 이름을 빌리는 경우를 두 그림으로 나타내세요. 이름 노드를 먼저 해제해도 언제나 안전하다고 일반화하지 마세요.
 */
void irq_domain_free_fwnode(struct fwnode_handle *fwnode)
{
	struct irqchip_fwid *fwid;

	if (!fwnode || WARN_ON(!is_fwnode_irqchip(fwnode)))
		return;

	fwid = container_of(fwnode, struct irqchip_fwid, fwnode);
	kfree(fwid->name);
	kfree(fwid);
}
EXPORT_SYMBOL_GPL(irq_domain_free_fwnode);

static int alloc_name(struct irq_domain *domain, char *base, enum irq_domain_bus_token bus_token)
{
	if (bus_token == DOMAIN_BUS_ANY)
		domain->name = kasprintf(GFP_KERNEL, "%s", base);
	else
		domain->name = kasprintf(GFP_KERNEL, "%s-%d", base, bus_token);
	if (!domain->name)
		return -ENOMEM;

	domain->flags |= IRQ_DOMAIN_NAME_ALLOCATED;
	return 0;
}

/* 학습 해설
 * Domain 이름 만들기: 문자열 소유권 표시와 경로 문자 치환
 * 펌웨어 경로를 디버그 파일 이름으로 사용하면 슬래시가 디렉터리 구분자로 해석될 수 있어 이름의 형식을 조정해야 합니다.
 * alloc_name은 base에 필요하면 bus token 숫자를 붙여 할당합니다. alloc_fwnode_name은 %pfw 형식으로 펌웨어 경로에 선택적 suffix와 token을 붙인 뒤 슬래시를 콜론으로 바꿉니다. suffix 포인터가 NULL이 아니면 구분자 하이픈도 붙으므로 빈 문자열 포인터와 NULL은 같은 형식이 아닐 수 있습니다. alloc_unknown_name은 원자 카운터 증가값으로 unknown-id 이름을 만듭니다. 세 함수는 이름 할당 실패를 -ENOMEM으로 반환하고 성공 시 IRQ_DOMAIN_NAME_ALLOCATED를 세웁니다. alloc_name과 alloc_unknown_name은 kasprintf 결과를 domain->name에 직접 대입하므로 실패하면 그 필드는 NULL입니다. 기존 이름을 자동 free하거나 보존하는 교체 API는 아닙니다. alloc_fwnode_name은 지역 name에 먼저 할당하여 실패 때 domain->name 대입까지 진행하지 않는 차이가 있습니다.
 * 경로 /soc/intc를 이름에 쓸 때 :soc:intc 형태로 바뀌는 이유를 적으세요. 알 수 없는 domain 이름은 카운터를 증가시킨 뒤 할당하므로 실패한 번호가 나중 성공 이름에서 빠질 수 있습니다. 예를 들어 base=intc, token=ANY이면 intc이고 token=3이면 intc-3입니다. unknown id=7이면 unknown-7 또는 unknown-7-3입니다. alloc_name은 슬래시 치환을 하지 않으며 그 처리는 alloc_fwnode_name에만 있습니다.
 */
static int alloc_fwnode_name(struct irq_domain *domain, const struct fwnode_handle *fwnode,
			     enum irq_domain_bus_token bus_token, const char *suffix)
{
	const char *sep = suffix ? "-" : "";
	const char *suf = suffix ? : "";
	char *name;

	if (bus_token == DOMAIN_BUS_ANY)
		name = kasprintf(GFP_KERNEL, "%pfw%s%s", fwnode, sep, suf);
	else
		name = kasprintf(GFP_KERNEL, "%pfw%s%s-%d", fwnode, sep, suf, bus_token);
	if (!name)
		return -ENOMEM;

	/*
	 * fwnode paths contain '/', which debugfs is legitimately unhappy
	 * about. Replace them with ':', which does the trick and is not as
	 * offensive as '\'...
	 */
	domain->name = strreplace(name, '/', ':');
	domain->flags |= IRQ_DOMAIN_NAME_ALLOCATED;
	return 0;
}

static int alloc_unknown_name(struct irq_domain *domain, enum irq_domain_bus_token bus_token)
{

/* 학습 해설
 * Domain 이름 선택: 복사·차용·지원하지 않는 조합
 * domain의 식별 노드 종류마다 이름을 가져오는 방식과 소유권이 달라 같은 name 포인터라도 수명을 다르게 관리해야 합니다.
 * irq_domain_set_name은 irqchip fwnode에 name_suffix가 있으면 -EINVAL입니다. NAMED와 NAMED_ID는 alloc_name으로 복사합니다. 나머지 irqchip 타입은 fwid의 이름을 먼저 빌리고, BUS_ANY가 아니면 token을 붙인 사본을 만듭니다. OF·ACPI device·software 노드는 alloc_fwnode_name을 사용합니다. 이미 이름이 있으면 성공하고, 이름이 없으면 잘못된 비NULL fwnode에 오류 로그를 남긴 뒤 unknown 이름 할당을 시도합니다. 잘못된 종류의 로그가 곧바로 생성 실패 반환인 것은 아닙니다.
 * irqchip NAMED, irqchip 기본 타입+ANY, OF+suffix, 지원하지 않는 노드의 네 경로를 그리세요. 실제 문자열 할당 함수가 호출되는 곳과 포인터만 빌리는 곳을 표시하세요.
 */
static int irq_domain_set_name(struct irq_domain *domain, const struct irq_domain_info *info)
{
	enum irq_domain_bus_token bus_token = info->bus_token;
	const struct fwnode_handle *fwnode = info->fwnode;

	if (is_fwnode_irqchip(fwnode)) {
		struct irqchip_fwid *fwid = container_of(fwnode, struct irqchip_fwid, fwnode);

		/*
		 * The name_suffix is only intended to be used to avoid a name
		 * collision when multiple domains are created for a single
		 * device and the name is picked using a real device node.
		 * (Typical use-case is regmap-IRQ controllers for devices
		 * providing more than one physical IRQ.) There should be no
		 * need to use name_suffix with irqchip-fwnode.
		 */
		if (info->name_suffix)
			return -EINVAL;

		switch (fwid->type) {
		case IRQCHIP_FWNODE_NAMED:
		case IRQCHIP_FWNODE_NAMED_ID:
			return alloc_name(domain, fwid->name, bus_token);
		default:
			domain->name = fwid->name;
			if (bus_token != DOMAIN_BUS_ANY)

/* 학습 해설
 * Domain 생성 조건: 직접 매핑과 선형 역매핑을 섞지 않기
 * 서로 다른 번호 변환 방식의 설정을 동시에 넣으면 저장 구조와 조회 규칙이 맞지 않을 수 있어 생성 전에 조합을 검사합니다.
 * __irq_domain_create는 size와 direct_max가 동시에 있거나, NOMAP 빌드 지원 없이 direct_max가 있거나, direct_max가 있는데 hwirq_max와 다르면 WARN_ON 뒤 ERR_PTR(-EINVAL)입니다. 정상 입력이면 struct_size(domain,revmap,size)만큼 NUMA 노드를 고려해 0 초기화 할당합니다. 실패는 ERR_PTR(-ENOMEM)입니다. 이름 설정이 실패하면 domain 메모리를 해제하고 해당 오류를 오류 포인터로 반환합니다.
 * size=16,direct_max=16을 넣은 경우와 size=0,direct_max=hwirq_max인 경우를 비교하세요. 첫 조합은 선형 저장 공간과 직접 매핑 범위를 동시에 요구해 이 검사에서 거절됩니다.
 */
static struct irq_domain *__irq_domain_create(const struct irq_domain_info *info)
{
	struct irq_domain *domain;
	int err;

	if (WARN_ON((info->size && info->direct_max) ||
		    (!IS_ENABLED(CONFIG_IRQ_DOMAIN_NOMAP) && info->direct_max) ||
		    (info->direct_max && info->direct_max != info->hwirq_max)))
		return ERR_PTR(-EINVAL);

	domain = kzalloc_node(struct_size(domain, revmap, info->size),
			      GFP_KERNEL, of_node_to_nid(to_of_node(info->fwnode)));
	if (!domain)
		return ERR_PTR(-ENOMEM);

	err = irq_domain_set_name(domain, info);
	if (err) {
		kfree(domain);
		return ERR_PTR(err);
	}

	domain->fwnode = fwnode_handle_get(info->fwnode);
	fwnode_dev_initialized(domain->fwnode, true);

	/* Fill structure */
	INIT_RADIX_TREE(&domain->revmap_tree, GFP_KERNEL);

/* 학습 해설
 * Domain 내부 초기화: 이름 이후 참조·역매핑·콜백 준비
 * domain을 다른 코드가 찾기 전에 조회 자료구조와 콜백, 식별 노드의 참조를 준비해야 미완성 객체가 노출되지 않습니다.
 * 이름 설정 뒤 fwnode_handle_get의 반환 포인터를 저장하고 fwnode_dev_initialized(true)를 표시합니다. revmap_tree를 초기화하고 ops·host_data·bus_token·hwirq_max를 저장합니다. direct_max가 있으면 NO_MAP 플래그를 세우고 revmap_size에 size를 넣습니다. mutex를 초기화하고 root를 자기 자신으로 둔 뒤 irq_domain_check_hierarchy를 호출합니다. 이 함수 자체는 전역 domain 목록에 추가하지 않고 준비된 객체를 반환합니다.
 * 할당→이름→노드 참조→저장 구조와 필드→잠금→계층 확인 순서를 그리세요. host_data 포인터 대입이 컨트롤러 전용 객체 전체의 복사를 뜻하지 않는 것도 확인하세요.
 */
static struct irq_domain *__irq_domain_create(const struct irq_domain_info *info)
{
	struct irq_domain *domain;
	int err;

	if (WARN_ON((info->size && info->direct_max) ||
		    (!IS_ENABLED(CONFIG_IRQ_DOMAIN_NOMAP) && info->direct_max) ||
		    (info->direct_max && info->direct_max != info->hwirq_max)))
		return ERR_PTR(-EINVAL);

	domain = kzalloc_node(struct_size(domain, revmap, info->size),
			      GFP_KERNEL, of_node_to_nid(to_of_node(info->fwnode)));
	if (!domain)
		return ERR_PTR(-ENOMEM);

	err = irq_domain_set_name(domain, info);
	if (err) {
		kfree(domain);
		return ERR_PTR(err);
	}

	domain->fwnode = fwnode_handle_get(info->fwnode);
	fwnode_dev_initialized(domain->fwnode, true);

	/* Fill structure */
	INIT_RADIX_TREE(&domain->revmap_tree, GFP_KERNEL);

/* 학습 해설
 * Domain 공개와 최종 free: 전역 목록 잠금과 이름 소유권
 * 여러 컨트롤러가 domain을 만들고 검색할 수 있어 전역 목록 변경을 직렬화하고 최종 해제에서는 자신이 소유한 메모리만 반납해야 합니다.
 * __irq_domain_publish는 irq_domain_mutex를 잡고 debugfs 항목을 만들고 list_add로 전역 목록 앞에 넣은 뒤 풉니다. CONFIG_GENERIC_IRQ_DEBUGFS가 꺼지면 debugfs helper는 빈 대체 구현입니다. irq_domain_free는 fwnode initialized 표시를 false로 바꾸고 참조를 put한 뒤 NAME_ALLOCATED일 때만 이름을 free하고 domain을 free합니다. 이 최종 free helper가 목록 연결을 스스로 제거하는 것은 아니므로 공개된 domain의 제거는 별도 remove 순서를 거쳐야 합니다.
 * 새 domain이 목록 앞에 들어가는 순서를 A 뒤 B 생성으로 그려 보세요. 최종 free에서 이름이 할당된 경우와 빌린 경우를 분리하고 노드 참조 get/put을 짝지으세요.
 */
static void __irq_domain_publish(struct irq_domain *domain)
{
	mutex_lock(&irq_domain_mutex);
	debugfs_add_domain_dir(domain);
	list_add(&domain->link, &irq_domain_list);
	mutex_unlock(&irq_domain_mutex);

	pr_debug("Added domain %s\n", domain->name);
}

static void irq_domain_free(struct irq_domain *domain)
{
	fwnode_dev_initialized(domain->fwnode, false);
	fwnode_handle_put(domain->fwnode);
	if (domain->flags & IRQ_DOMAIN_NAME_ALLOCATED)
		kfree(domain->name);
	kfree(domain);
}

static void irq_domain_instantiate_descs(const struct irq_domain_info *info)
{
	if (!IS_ENABLED(CONFIG_SPARSE_IRQ))
		return;

	if (irq_alloc_descs(info->virq_base, info->virq_base, info->size,
			    of_node_to_nid(to_of_node(info->fwnode))) < 0) {

/* 학습 해설
 * Domain 구성 순서: generic chip과 init 콜백 실패 되돌리기
 * 기본 domain 객체 생성 뒤에도 컨트롤러용 chip 준비나 드라이버 초기화가 실패할 수 있어 어디까지 성공했는지에 따라 정리가 달라집니다.
 * __irq_domain_instantiate는 생성 실패를 그대로 반환하고, 성공하면 domain_flags와 exit 콜백을 저장합니다. 계층 지원에서 parent가 있으면 parent와 같은 root를 사용합니다. dgc_info가 있으면 generic chip을 준비하고 실패 시 domain free로 갑니다. init 콜백 실패는 generic chip을 준비한 경우 그것부터 제거하고 domain을 free합니다. 이 두 단계가 성공한 뒤에만 __irq_domain_publish를 호출합니다. 실패 정리에서 info->exit를 호출하는 코드는 없습니다.
 * generic chip 준비 실패와 init 실패의 goto 목적지를 각각 따라가세요. init이 자신의 부분 초기화 실패를 되돌리는 책임을 어떻게 약속하는지는 해당 콜백 구현과 함께 봐야 합니다.
 */
static struct irq_domain *__irq_domain_instantiate(const struct irq_domain_info *info,
						   bool cond_alloc_descs, bool force_associate)
{
	struct irq_domain *domain;
	int err;

	domain = __irq_domain_create(info);
	if (IS_ERR(domain))
		return domain;

	domain->flags |= info->domain_flags;
	domain->exit = info->exit;

#ifdef CONFIG_IRQ_DOMAIN_HIERARCHY
	if (info->parent) {
		domain->root = info->parent->root;
		domain->parent = info->parent;
	}
#endif

	if (info->dgc_info) {
		err = irq_domain_alloc_generic_chips(domain, info->dgc_info);
		if (err)
			goto err_domain_free;
	}

/* 학습 해설
 * Domain descriptor 준비: 실패 로그 뒤에도 계속하는 경로
 * 레거시 시스템은 IRQ descriptor가 이미 준비돼 있을 수 있어 할당 실패를 생성 전체 실패로 단정하지 않는 호환 경로가 있습니다.
 * irq_domain_instantiate_descs는 SPARSE_IRQ가 아닌 빌드에서는 즉시 반환합니다. sparse 구성에서는 info->virq_base부터 info->size개 descriptor를 요청합니다. 결과가 음수면 이미 할당된 것으로 가정한다는 로그를 남기지만 오류를 반환하지 않습니다. instantiate는 cond_alloc_descs가 참이고 virq_base>0일 때 이 helper를 호출합니다. 이어 force_associate 또는 virq_base>0이면 size-hwirq_base개의 연속 연결을 시도합니다. domain 공개는 이 준비와 연결보다 먼저 수행됩니다.
 * cond_alloc_descs=false, virq_base>0이면 descriptor 요청 helper는 생략해도 매핑 연결은 시도되는 차이를 표로 적으세요. 로그의 가정이 실제 모든 descriptor 존재를 증명하지는 않는다는 점도 확인하세요.
 */
static void irq_domain_instantiate_descs(const struct irq_domain_info *info)
{
	if (!IS_ENABLED(CONFIG_SPARSE_IRQ))
		return;

	if (irq_alloc_descs(info->virq_base, info->virq_base, info->size,
			    of_node_to_nid(to_of_node(info->fwnode))) < 0) {
		pr_info("Cannot allocate irq_descs @ IRQ%d, assuming pre-allocated\n",
			info->virq_base);
	}
}

static struct irq_domain *__irq_domain_instantiate(const struct irq_domain_info *info,
						   bool cond_alloc_descs, bool force_associate)
{
	struct irq_domain *domain;
	int err;

	domain = __irq_domain_create(info);
	if (IS_ERR(domain))
		return domain;

	domain->flags |= info->domain_flags;
	domain->exit = info->exit;

#ifdef CONFIG_IRQ_DOMAIN_HIERARCHY

/* 학습 해설
 * Domain 생성 wrapper: 오류 포인터와 NULL의 계약 차이
 * 같은 내부 구현을 부르는 API라도 바깥 wrapper가 반환 형식을 바꾸면 호출자의 실패 검사도 달라져야 합니다.
 * irq_domain_instantiate는 __irq_domain_instantiate(info,false,false)의 결과를 그대로 반환해 ERR_PTR 계약을 유지합니다. irq_domain_create_simple은 fwnode·size·hwirq_max=size·first_irq·ops·host_data를 info로 묶고 true,false 옵션을 넘깁니다. 내부 오류 포인터는 NULL로 바꿉니다. first_irq=0이면 번호를 미리 연결하지 않고 필요할 때 동적으로 연결하는 경로이며, 양수이면 조건부 descriptor 준비와 연속 연결을 시도합니다.
 * 같은 내부 -ENOMEM이 instantiate에서는 ERR_PTR, create_simple에서는 NULL이 되는 것을 그리세요. 성공 domain을 얻는 것과 각 레거시 번호의 실제 연결 상태를 구분하세요.
 */
struct irq_domain *irq_domain_instantiate(const struct irq_domain_info *info)
{
	return __irq_domain_instantiate(info, false, false);
}
EXPORT_SYMBOL_GPL(irq_domain_instantiate);

/**
 * irq_domain_remove() - Remove an irq domain.
 * @domain: domain to remove
 *
 * This routine is used to remove an irq domain. The caller must ensure
 * that all mappings within the domain have been disposed of prior to
 * use, depending on the revmap type.
 */
void irq_domain_remove(struct irq_domain *domain)
{
	if (domain->exit)
		domain->exit(domain);

	mutex_lock(&irq_domain_mutex);
	debugfs_remove_domain_dir(domain);

	WARN_ON(!radix_tree_empty(&domain->revmap_tree));

	list_del(&domain->link);

/* 학습 해설
 * 레거시 IRQ domain: 하드웨어 시작 오프셋을 포함한 크기
 * 컨트롤러의 유효한 하드웨어 번호가 0부터 시작하지 않아도 배열 인덱스와 연결 개수를 일치시켜야 합니다.
 * irq_domain_create_legacy는 size와 hwirq_max를 first_hwirq+size로 설정하고 hwirq_base에 first_hwirq, virq_base에 first_irq를 넣습니다. 내부 호출 옵션은 false,true라 descriptor 조건부 할당은 요청하지 않고 연속 연결은 강제 요청합니다. 내부 연결 개수 size-hwirq_base는 여기서 원래 size가 됩니다. irq_domain_add_legacy는 Device Tree 노드를 fwnode로 바꿔 이 함수에 위임합니다. 반환 오류는 NULL로 변환됩니다.
 * first_hwirq=4, 입력 size=3, first_irq=20이면 저장 범위 상한은 7이고 연결은 hwirq 4·5·6과 virq 20·21·22입니다. 유효 입력에서 합계가 표현 범위를 넘지 않아야 합니다.
 */
struct irq_domain *irq_domain_create_legacy(struct fwnode_handle *fwnode,
					 unsigned int size,
					 unsigned int first_irq,
					 irq_hw_number_t first_hwirq,
					 const struct irq_domain_ops *ops,
					 void *host_data)
{
	struct irq_domain_info info = {
		.fwnode		= fwnode,
		.size		= first_hwirq + size,
		.hwirq_max	= first_hwirq + size,
		.hwirq_base	= first_hwirq,
		.virq_base	= first_irq,
		.ops		= ops,
		.host_data	= host_data,
	};
	struct irq_domain *domain = __irq_domain_instantiate(&info, false, true);

	return IS_ERR(domain) ? NULL : domain;
}
EXPORT_SYMBOL_GPL(irq_domain_create_legacy);

