/* 학습 해설
 * Domain 제거: 매핑부터 정리해야 하는 호출자 계약
 * domain 객체를 먼저 해제하면 남아 있는 IRQ 매핑이 사라진 domain을 참조할 수 있어 제거 순서가 중요합니다.
 * irq_domain_remove의 계약은 호출자가 모든 매핑을 먼저 처분하는 것입니다. exit 콜백이 있으면 전역 목록 잠금 전에 호출하고, 잠금 안에서 debugfs를 제거하며 revmap_tree가 비었는지 경고 검사하고 목록에서 뺍니다. 제거 대상이 기본 domain이면 기본 포인터를 NULL로 바꿉니다. 잠금 해제 뒤 DESTROY_GC 플래그가 있을 때 generic chips를 제거하고 최종 domain free를 수행합니다. 트리 경고가 모든 선형 슬롯을 정리하거나 일반 실패 반환을 만드는 것은 아닙니다.
 * 매핑 해제→exit→목록·debugfs 제거→선택적 generic chip 정리→노드 참조·이름·domain free 순서를 그리세요. exit 콜백을 전역 mutex 안에서 실행한다고 읽지 마세요.
 */
void irq_domain_remove(struct irq_domain *domain)
{
	if (domain->exit)
		domain->exit(domain);

	mutex_lock(&irq_domain_mutex);
	debugfs_remove_domain_dir(domain);

	WARN_ON(!radix_tree_empty(&domain->revmap_tree));

	list_del(&domain->link);

	/*
	 * If the going away domain is the default one, reset it.
	 */
	if (unlikely(irq_default_domain == domain))
		irq_set_default_host(NULL);

	mutex_unlock(&irq_domain_mutex);

	if (domain->flags & IRQ_DOMAIN_FLAG_DESTROY_GC)
		irq_domain_remove_generic_chips(domain);

	pr_debug("Removed domain %s\n", domain->name);
	irq_domain_free(domain);
}

/* 학습 해설
 * Domain bus token 변경: 이름 할당 실패의 부분 반영
 * 값 변경과 그 값을 보여 주는 이름 갱신이 별도 단계이면 중간 할당 실패 때 둘이 다른 상태로 남을 수 있습니다.
 * 같은 token이면 바로 반환합니다. 다르면 전역 mutex를 잡고 bus_token을 먼저 바꾼 뒤 현재 이름에 새 token을 덧붙인 문자열을 할당합니다. 실패하면 잠금을 풀고 반환하지만 token은 원래 값으로 되돌리지 않습니다. 성공하면 이전 debugfs 항목을 제거하고 소유한 이름만 free하거나 이름 소유 표시를 새로 세운 뒤 새 이름으로 debugfs를 다시 만듭니다. 원래 기본 이름을 저장해 매번 다시 만드는 함수는 아니므로 연속 변경은 현재 이름 뒤에 접미사를 누적할 수 있습니다.
 * 이름 chip, token 변경 1→2에서 이름이 chip-2가 되는 경로와 할당 실패해 이름 chip이 남지만 token은 2인 경로를 그리세요. 다음 변경은 현재 name을 기준으로 한다는 점을 확인하세요.
 */
void irq_domain_update_bus_token(struct irq_domain *domain,
				 enum irq_domain_bus_token bus_token)
{
	char *name;

	if (domain->bus_token == bus_token)
		return;

	mutex_lock(&irq_domain_mutex);

	domain->bus_token = bus_token;

	name = kasprintf(GFP_KERNEL, "%s-%d", domain->name, bus_token);
	if (!name) {
		mutex_unlock(&irq_domain_mutex);
		return;
	}

	debugfs_remove_domain_dir(domain);

	if (domain->flags & IRQ_DOMAIN_NAME_ALLOCATED)
		kfree(domain->name);
	else
		domain->flags |= IRQ_DOMAIN_NAME_ALLOCATED;

	domain->name = name;

/* 학습 해설
 * Firmware 사양으로 domain 찾기: select·match·기본 비교의 우선순위
 * 펌웨어가 알려 준 IRQ 정보가 어떤 컨트롤러에 속하는지 찾을 때 장치별 해석 콜백과 일반 식별자 비교를 구분해야 합니다.
 * irq_find_matching_fwspec은 전역 mutex 안에서 domain 목록을 순회합니다. select가 있고 요청 token이 ANY가 아니면 select를 사용합니다. 아니면 match가 있으면 OF 노드 변환과 token을 전달합니다. 둘 다 선택되지 않으면 비NULL fwnode의 포인터 일치와 ANY 또는 정확한 token 일치를 검사합니다. rc가 0이 아닌 첫 domain을 반환하고 없으면 NULL입니다. 이 호출부는 rc의 음수를 별도 오류로 처리하지 않으므로 콜백은 음수 오류가 아닌 일치 여부 계약을 지켜야 합니다. select가 false여도 같은 domain에서 match를 다시 시도하는 구조는 아닙니다.
 * select 있음·ANY 요청이면 select를 건너뛰고 match 또는 기본 비교로 가는 표를 만드세요. 생성 시 목록 앞에 넣으므로 여러 domain이 맞는 경우 첫 일치가 어느 항목인지 순서에도 영향받습니다.
 */
