	/*
	 * We might want to match the legacy controller last since
	 * it might potentially be set to match all interrupts in
	 * the absence of a device node. This isn't a problem so far
	 * yet though...
	 *
	 * bus_token == DOMAIN_BUS_ANY matches any domain, any other
	 * values must generate an exact match for the domain to be
	 * selected.
	 */
	mutex_lock(&irq_domain_mutex);
	list_for_each_entry(h, &irq_domain_list, link) {
		if (h->ops->select && bus_token != DOMAIN_BUS_ANY)
			rc = h->ops->select(h, fwspec, bus_token);
		else if (h->ops->match)
			rc = h->ops->match(h, to_of_node(fwnode), bus_token);
		else
			rc = ((fwnode != NULL) && (h->fwnode == fwnode) &&
			      ((bus_token == DOMAIN_BUS_ANY) ||

/* 학습 해설
 * 기본 IRQ domain: 편의 포인터와 수명 관리의 차이
 * 펌웨어 노드로 컨트롤러를 찾기 어려운 오래된 플랫폼은 기본 domain을 사용할 수 있지만 전역 포인터 대입이 소유권 관리까지 대신하지는 않습니다.
 * irq_set_default_host는 디버그 로그 뒤 irq_default_domain에 포인터를 대입하고 irq_get_default_host는 그 값을 반환합니다. 두 함수 본문에 별도의 객체 복사·참조 증가·mutex 획득은 없습니다. getter는 기본값이 없으면 NULL을 그대로 반환하고, 반환한 포인터를 사용한다고 객체 수명이 자동 연장되지 않습니다. 매핑 생성 함수 일부가 NULL domain 입력을 이 기본값으로 대체합니다. 원문은 현대 코드에서는 firmware→fwnode 매핑을 사용할 수 없는 시스템 외에는 이 편의 API를 쓰지 말라고 설명합니다.
 * 기본값 없음, 기본 domain A 설정, NULL 입력으로 매핑 요청, A 제거로 기본값 NULL의 흐름을 그리세요. 포인터 설정과 domain 생성은 별도 단계입니다.
 */
void irq_set_default_host(struct irq_domain *domain)
{
	pr_debug("Default domain set to @0x%p\n", domain);

	irq_default_domain = domain;
}
EXPORT_SYMBOL_GPL(irq_set_default_host);

/**
 * irq_get_default_host() - Retrieve the "default" irq domain
 *
 * Returns: the default domain, if any.
 *
 * Modern code should never use this. This should only be used on
 * systems that cannot implement a firmware->fwnode mapping (which
 * both DT and ACPI provide).
 */
struct irq_domain *irq_get_default_host(void)
{
	return irq_default_domain;
}
EXPORT_SYMBOL_GPL(irq_get_default_host);

