/* 학습 해설
 * NOMAP 상태: 빌드 지원과 객체 플래그가 모두 필요하다
 * 하드웨어 번호를 Linux 번호로 직접 사용할 수 있는 경우에는 별도 역조회 표를 생략할 수 있지만 모든 domain에 자동 적용되지는 않습니다.
 * irq_domain_is_nomap은 CONFIG_IRQ_DOMAIN_NOMAP이 켜지고 객체에 IRQ_DOMAIN_FLAG_NO_MAP도 있을 때 참입니다. irq_domain_set_mapping과 clear_mapping은 먼저 root mutex 보유를 lockdep_assert_held로 확인하고 NOMAP이면 저장 구조를 바꾸지 않고 반환합니다. 직접 매핑 함수를 호출할 수 있는 빌드와 해당 domain이 실제 NO_MAP인지의 판단은 다른 조건입니다. assert는 잠금을 대신 잡지 않습니다.
 * 빌드 지원 true/false와 객체 플래그 true/false의 2×2 표를 만드세요. 두 조건이 모두 참일 때만 역매핑 쓰기·삭제가 생략됩니다.
 */
static bool irq_domain_is_nomap(struct irq_domain *domain)
{
	return IS_ENABLED(CONFIG_IRQ_DOMAIN_NOMAP) &&
	       (domain->flags & IRQ_DOMAIN_FLAG_NO_MAP);
}

static void irq_domain_clear_mapping(struct irq_domain *domain,
				     irq_hw_number_t hwirq)
{
	lockdep_assert_held(&domain->root->mutex);

	if (irq_domain_is_nomap(domain))
		return;

	if (hwirq < domain->revmap_size)
		rcu_assign_pointer(domain->revmap[hwirq], NULL);
	else
		radix_tree_delete(&domain->revmap_tree, hwirq);
}

static void irq_domain_set_mapping(struct irq_domain *domain,
				   irq_hw_number_t hwirq,
				   struct irq_data *irq_data)
{
	/*
	 * This also makes sure that all domains point to the same root when
	 * called from irq_domain_insert_irq() for each domain in a hierarchy.
	 */

/* 학습 해설
 * IRQ 역매핑의 배열과 트리: 조밀한 번호와 큰 번호를 함께 다루기
 * 자주 쓰는 작은 번호는 배열로 빠르게 찾되 매우 큰 하드웨어 번호까지 배열 칸을 확보하면 비어 있는 공간을 많이 쓰게 됩니다.
 * NOMAP이 아니면 hwirq<revmap_size인 항목은 revmap[hwirq]에 irq_data 포인터를 rcu_assign_pointer로 공개합니다. 그 이상 번호는 revmap_tree에 radix_tree_insert합니다. irq_domain_clear_mapping도 같은 기준으로 배열 슬롯에 NULL을 공개하거나 트리 항목을 삭제합니다. 삭제 helper는 root mutex 보유를 진단할 뿐 직접 잠금을 잡지 않으며 NOMAP이면 바로 반환합니다. mapcount 감소나 irq_data의 kfree는 이 helper 본문에 없습니다. 배열 슬롯을 비우는 것과 그 슬롯이 가리켰던 객체를 해제하는 것은 다른 작업입니다. 배열의 길이는 domain 생성 시 size로 확보한 크기이고 hwirq_max는 허용 번호 상한이므로 둘을 같다고 가정할 수 없습니다. 이 helper는 트리 삽입의 반환 오류를 상위로 전달하는 반환형을 갖지 않습니다.
 * revmap_size=32, hwirq_max=1000000일 때 5는 배열, 900000은 트리입니다. 8바이트 포인터를 가정한 1000000칸 배열은 8000000바이트지만 32칸은 256바이트이며 트리에는 별도 노드 비용이 듭니다.
 */
static void irq_domain_set_mapping(struct irq_domain *domain,
				   irq_hw_number_t hwirq,
				   struct irq_data *irq_data)
{
	/*
	 * This also makes sure that all domains point to the same root when
	 * called from irq_domain_insert_irq() for each domain in a hierarchy.
	 */
	lockdep_assert_held(&domain->root->mutex);

	if (irq_domain_is_nomap(domain))
		return;

	if (hwirq < domain->revmap_size)
		rcu_assign_pointer(domain->revmap[hwirq], irq_data);
	else
		radix_tree_insert(&domain->revmap_tree, hwirq, irq_data);
}

