/* 학습 해설
 * 연속 IRQ 연결: 반복 호출이 전체 원자 작업은 아니다
 * 연속된 번호 범위를 설정하는 함수라도 중간 오류를 감지하고 앞선 성공을 되돌리는 코드가 없다면 범위 전체 성공을 보장하지 않습니다.
 * irq_domain_associate_many는 i=0부터 count 미만까지 irq_base+i와 hwirq_base+i를 irq_domain_associate에 전달합니다. 반환값을 검사하거나 실패 시 중단하지 않습니다. 공개 associate는 매 호출마다 root mutex를 잡고 locked helper를 실행한 뒤 풉니다. 따라서 many는 전체 범위를 한 번의 잠금으로 감싸는 일괄 트랜잭션이 아니고 각 항목의 성공·실패가 섞일 수 있습니다.
 * 3개 중 첫째 성공, 둘째 실패, 셋째 성공을 가정해 최종 두 매핑이 남는 흐름을 그리세요. count는 int이고 0 또는 음수이면 반복문은 실행되지 않습니다. 다만 그 전에 OF 노드 조회와 디버그 로그 준비는 수행되므로 유효 domain 전제까지 사라지는 것은 아닙니다.
 */
void irq_domain_associate_many(struct irq_domain *domain, unsigned int irq_base,
			       irq_hw_number_t hwirq_base, int count)
{
	struct device_node *of_node;
	int i;

	of_node = irq_domain_get_of_node(domain);
	pr_debug("%s(%s, irqbase=%i, hwbase=%i, count=%i)\n", __func__,
		of_node_full_name(of_node), irq_base, (int)hwirq_base, count);

	for (i = 0; i < count; i++)
		irq_domain_associate(domain, irq_base + i, hwirq_base + i);
}
EXPORT_SYMBOL_GPL(irq_domain_associate_many);

